def preco_com_taxa(p, adicional=0):
    # Cálculo unificado: taxa de 10% mais o valor do adicional
    total = p * 1.10 + adicional
    return round(total, 2)

def total_a(p):
    return preco_com_taxa(p)

def total_b(p):
    return preco_com_taxa(p, adicional=5)

def total_c(p):
    return preco_com_taxa(p, adicional=12)
